import re
import os


class RtgBuild:
    _re_build_release_and_number = re.compile(r'RTG_RL(?P<BUILD_RELEASE>\d+.\d+)_BLD-(?P<BUILD_NUMBER>\d+)')

    _rpm_package = "rtg-{}-{}.x86_64.rpm"
    _deb_package = "rtg_{}-{}_amd64.deb"
    _build_string = "RTG_RL{}_BLD-{}"

    def __init__(self, system_type, device, build_string,
                 base_download_link="https://artifactory-espoo1.ext.net.nokia.com/artifactory/mn-cusrelease-local/rtg/release/",
                 default_package_localization='/tmp', proxy=None):
        self.root_state = device.ws_root
        self.basic_state = device.ws
        self.system_type = system_type
        self.device = device
        self.default_package_localization = default_package_localization
        self.base_download_link = base_download_link
        self.proxy = proxy

        self.installation_path = ''

        rtg_build_parameters = self.get_build_release_and_number(build_string)
        self.build_release = rtg_build_parameters["BUILD_RELEASE"]
        self.build_number = rtg_build_parameters["BUILD_NUMBER"]

        self.rpm_package = self._rpm_package.format(self.build_release, self.build_number)
        self.deb_package = self._deb_package.format(self.build_release, self.build_number)
        self.build_string = self._build_string.format(self.build_release, self.build_number)

    def set_debian_build_and_installation_path(self, timeout=1800):
        self.installation_path = self.get_package_and_location(self.deb_package, download_timeout=timeout)

    def set_suse_build_and_installation_path(self, timeout=1800):
        self.installation_path = self.get_package_and_location(self.rpm_package, download_timeout=timeout)

    def get_package_and_location(self, build_package_name, search_timeout=300, download_timeout=1800):
        build_localization = self.search_for_package(build_package_name, search_timeout)
        if not build_localization:
            self.download_package(build_package_name, download_timeout)
            return os.path.join(self.default_package_localization, build_package_name)
        return build_localization

    def download_package(self, build_package_name, timeout=1800):
        download_options = self.get_download_options(build_package_name)
        download_build_cmd = self.device.get_cmd(cmd_name="wget",
                                                 cmd_params={
                                                     "options": download_options})
        download_build_cmd(timeout=timeout)
        result = download_build_cmd.result()["RESULT"]
        if result == [] or re.search(r"ERROR\s+404", download_build_cmd.result()["RESULT"][0]):
            raise RuntimeError("Package could not be downloaded")

    def get_download_options(self, build_package_name):
        url_link = self.create_download_link(build_package_name)
        local_build_path = os.path.join(self.default_package_localization, build_package_name)
        link_with_options = "{} -O {}".format(url_link, local_build_path)
        if self.proxy:
            link_with_options = "{} -e use_proxy=yes -e http_proxy={}".format(link_with_options, self.proxy)
        return link_with_options

    def create_download_link(self, build_package_name):
        return "{}{}/{}".format(self.base_download_link, self.build_string, build_package_name)

    def get_build_release_and_number(self, build_string):
        return re.search(self._re_build_release_and_number, build_string).groupdict()

    def search_for_package(self, package, timeout=300):
        self.device.goto_state(self.root_state)
        find_cmd = self.device.get_cmd(cmd_name="find", cmd_params={"options": self._get_find_options(package)})
        find_result = find_cmd(timeout=timeout)
        self.device.goto_state(self.basic_state)
        if find_result['RESULT'] and re.search(package,['RESULT'][0]):
            return find_result['RESULT'][0]
        else:
            return None

    def _get_find_options(self, package):
        return self.default_package_localization + " -name {}".format(package)
